  function formatError(error, fallback) { var details = error && error.details || {}; var refs = details.references; var suffix = Array.isArray(refs) && refs.length ? " 当前引用：" + refs.map(function (item) { return item.label; }).join("、") : ""; if (error && error.code === 'SOUND_COMBO_PACKAGE_SOUND_ASSET_MISSING') { var ids = Array.isArray(details.soundIds) ? details.soundIds : []; return '配置包缺少音频，请先导入 .nhsound 音频包。缺少：' + (ids.length ? ids.join('、') : '未提供音频标识'); } return (error && error.code ? error.code + " · " : "") + String(error && error.message || error || fallback) + suffix; }
  function selectedEventId() { return $("config-event-id").value; }
  function syncSelectedBinding(preserveDraft) { if (preserveDraft) return; var profile = initialData && (initialData.profile || initialData.settings && initialData.settings.profile) || {}; var overrides = Array.isArray(profile.soundOverrides) ? profile.soundOverrides : []; var eventId = selectedEventId(); var binding = overrides.find(function (entry) { return entry.eventId === eventId; }); var select = $("config-sound"); if (!select) return; var soundId = binding && binding.soundId || ""; select.value = [].slice.call(select.options).some(function (option) { return option.value === soundId; }) ? soundId : ""; $("config-volume").value = Math.round(Number.isFinite(binding && binding.volume) ? binding.volume * 100 : 100); $("config-volume-label").textContent = $("config-volume").value + "%"; }
  function renderSoundOptions(assets) { var select = $("config-sound"); if (!select) return; var selected = select.value; var options = '<option value="">未选择，使用 Windows 默认声音</option>' + (assets || []).filter(function (asset) { return asset.kind === "custom"; }).map(function (asset) { return '<option value="' + escapeText(asset.soundId) + '">' + escapeText(asset.name || asset.soundId) + '</option>'; }).join(""); select.innerHTML = options; if ([].slice.call(select.options).some(function (option) { return option.value === selected; })) select.value = selected; }
