  function renderAssets(assets, profile) { var custom = (assets || []).filter(function (asset) { return asset.kind === "custom"; }); var overrides = Array.isArray(profile.soundOverrides) ? profile.soundOverrides : []; if (!custom.length) return '<div class="empty-state">音频库还是空的。添加本地音频后，就可以在上面的声音配置中选择它。</div>'; return custom.map(function (asset) { var refs = overrides.filter(function (binding) { return binding.soundId === asset.soundId; }); var refLabels = refs.map(function (binding) { return (categoryLabels[binding.category] || binding.category) + ' · ' + (eventLabels[binding.event] || binding.event); }); var warningText = refs.length ? '如果删除“' + escapeText(asset.name || asset.soundId) + '”，以下配置也会删除：' + escapeText(refLabels.join('；')) : '删除“' + escapeText(asset.name || asset.soundId) + '”后不可恢复。'; return '<div class="asset-row"><div class="asset-info"><strong>' + escapeText(asset.name || asset.soundId) + '</strong><span>' + escapeText(String(asset.format || "audio").toUpperCase()) + ' · ' + Number(asset.fileSizeBytes || 0).toLocaleString() + ' bytes · ' + (refs.length ? "已被 " + refs.length + " 个通知组合使用" : "尚未配置到通知组合") + '</span>' + (refs.length ? '<small>引用：' + escapeText(refLabels.join('；')) + '</small>' : '') + '</div><div class="row-actions"><button type="button" class="secondary asset-test" data-sound-id="' + escapeText(asset.soundId) + '">试听</button><button type="button" class="secondary asset-delete" data-sound-id="' + escapeText(asset.soundId) + '">删除</button></div><div class="delete-warning" data-delete-warning="' + escapeText(asset.soundId) + '" hidden>' + warningText + '<button type="button" class="asset-delete-confirm" data-sound-id="' + escapeText(asset.soundId) + '">确认删除</button></div></div>'; }).join(""); }
