    document.querySelectorAll('.binding-test').forEach(function (button) { button.onclick = function () { var target = effectRuleTargets.find(function (entry) { return entry.eventId === button.dataset.bindingEventId; }); testCombination({ eventId: button.dataset.bindingEventId, labels: [target ? target.categoryId : 'chat'], event: target ? target.eventTypeId : 'arrived', importance: 'normal', soundId: button.dataset.bindingSoundId }); }; });
    document.querySelectorAll('.binding-save').forEach(function (button) { button.onclick = function () { var row = button.closest('.binding-row'); var input = row && row.querySelector('.binding-volume-input'); var volume = Number(input && input.value) / 100; button.disabled = true; setStatus('config-feedback', '正在保存组合音量…', ''); jsonRequest('sound-asset-configure', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ eventId: button.dataset.bindingEventId, soundId: button.dataset.bindingSoundId, volume: volume }) }).then(function (data) { render(data); setStatus('config-feedback', '组合音量已保存。', 'success'); }).catch(function (error) { setStatus('config-feedback', formatError(error, '保存组合音量失败'), 'error'); }).finally(function () { button.disabled = false; }); }; });
