export function renderSoundSettingsFragment(currentUrl = '', initialData = null) {
  const fullPage = renderSoundSettingsPage(currentUrl, initialData);
  const styleStart = fullPage.indexOf('<style>') + '<style>'.length;
  const styleEnd = fullPage.indexOf('</style>', styleStart);
  const sectionStart = fullPage.indexOf('<section class="layout"');
  const sectionEnd = fullPage.indexOf('</section>', sectionStart);
  // The page navigation owns another script tag.  Taking the first <script>
  // here silently mounted navigation code as the sound-view code, so the
  // fragment had no sound button handlers at all.
  const soundScriptMarker = '<script>\n(function () { "use strict";\n  var initialData =';
  const scriptTagStart = fullPage.indexOf(soundScriptMarker);
  const scriptStart = scriptTagStart < 0 ? -1 : scriptTagStart + '<script>'.length;
  const scriptEnd = scriptStart < 0 ? -1 : fullPage.indexOf('</script>', scriptStart);
  if (styleStart < '<style>'.length || styleEnd < 0 || sectionStart < 0 || sectionEnd < 0 || scriptStart < '<script>'.length || scriptEnd < 0) return '<div class="settings-view-error">声音设置片段生成失败。</div>';
  const section = fullPage.slice(sectionStart, sectionEnd + '</section>'.length);
  const script = fullPage.slice(scriptStart, scriptEnd).replace('$("back-settings").addEventListener("click", function () { if (window.NotificationHubPageRouter) window.NotificationHubPageRouter.load("settings"); });', '');
  return `<style data-settings-view-style>${fullPage.slice(styleStart, styleEnd)}</style>${section}<script>${script}</script>`;
}

export default function registerSoundSettingsRoute(app, ctx) {
  const getPlugin = () => ctx?._notificationHubVNextSettingsApi ?? ctx?._notificationHubVNextPlugin;
  app.get('/settings-sound', (c) => {
    const plugin = getPlugin();
    const initialData = typeof plugin?.getSoundSettingsStatus === 'function' ? plugin.getSoundSettingsStatus() : null;
    return c.html(renderSoundSettingsPage(c?.req?.url ?? c?.req?.raw?.url ?? '', initialData));
  });
}
